<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Image Preview — Delete Confirmation</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #11182d;
      --panel-2: #18223d;
      --text: #eef2ff;
      --muted: #a8b3cf;
      --border: rgba(255, 255, 255, 0.1);
      --accent: #8fb4ff;
      --danger: #ff6b7a;
      --danger-strong: #ff8894;
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
      --radius: 24px;
    }

    * {
      box-sizing: border-box;
    }

    html, body {
      min-height: 100%;
    }

    body {
      margin: 0;
      font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(143, 180, 255, 0.15), transparent 42%),
        linear-gradient(180deg, #0a0f1e 0%, #0d1428 100%);
      color: var(--text);
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px;
    }

    .preview-shell {
      width: min(100%, 760px);
      display: grid;
      gap: 18px;
      padding: 28px;
      border: 1px solid var(--border);
      border-radius: calc(var(--radius) + 6px);
      background: rgba(12, 18, 36, 0.72);
      box-shadow: var(--shadow);
      backdrop-filter: blur(14px);
    }

    h1 {
      margin: 0;
      font-size: clamp(1.8rem, 4vw, 2.6rem);
      line-height: 1.1;
      letter-spacing: -0.03em;
    }

    .lede {
      margin: 0;
      color: var(--muted);
      max-width: 60ch;
    }

    figure {
      margin: 0;
      display: grid;
      gap: 18px;
    }

    .image-frame {
      padding: 14px;
      border-radius: var(--radius);
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03));
      border: 1px solid var(--border);
    }

    img {
      display: block;
      width: 100%;
      height: auto;
      border-radius: calc(var(--radius) - 10px);
      aspect-ratio: 16 / 10;
      object-fit: cover;
    }

    figcaption {
      color: var(--muted);
    }

    .actions {
      display: flex;
      justify-content: flex-start;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      font: inherit;
      font-weight: 650;
      cursor: pointer;
      transition: transform 160ms ease, background-color 160ms ease, box-shadow 160ms ease, border-color 160ms ease;
    }

    button:focus-visible {
      outline: 3px solid var(--accent);
      outline-offset: 3px;
    }

    .trigger {
      padding: 0.95rem 1.35rem;
      color: #fff;
      background: linear-gradient(180deg, #ff7381, #d94b63);
      box-shadow: 0 14px 30px rgba(217, 75, 99, 0.32);
    }

    .trigger:hover {
      transform: translateY(-1px);
      background: linear-gradient(180deg, var(--danger-strong), #da5a6e);
    }

    dialog {
      width: min(92vw, 440px);
      border: 1px solid var(--border);
      border-radius: 28px;
      padding: 0;
      background:
        linear-gradient(180deg, rgba(24, 34, 61, 0.98), rgba(13, 19, 36, 0.98));
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(3, 7, 18, 0.72);
      backdrop-filter: blur(4px);
    }

    .dialog-body {
      display: grid;
      gap: 18px;
      padding: 24px;
    }

    .dialog-title {
      margin: 0;
      font-size: 1.35rem;
      line-height: 1.2;
    }

    .dialog-copy {
      margin: 0;
      color: var(--muted);
    }

    .dialog-actions {
      display: flex;
      gap: 12px;
      justify-content: flex-end;
      flex-wrap: wrap;
    }

    .ghost,
    .destructive {
      padding: 0.85rem 1.2rem;
    }

    .ghost {
      color: var(--text);
      background: rgba(255, 255, 255, 0.08);
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    .ghost:hover {
      background: rgba(255, 255, 255, 0.12);
    }

    .destructive {
      color: #fff;
      background: linear-gradient(180deg, #ff7080, #df5068);
      box-shadow: 0 14px 28px rgba(223, 80, 104, 0.28);
    }

    .destructive:hover {
      background: linear-gradient(180deg, #ff8a96, #e05b71);
    }

    .dialog-icon {
      width: 52px;
      height: 52px;
      display: grid;
      place-items: center;
      border-radius: 16px;
      background: rgba(255, 107, 122, 0.16);
      color: #ff9aa4;
      font-size: 1.5rem;
    }

    .dialog-header {
      display: flex;
      gap: 16px;
      align-items: flex-start;
    }

    @media (max-width: 520px) {
      main {
        padding: 16px;
      }

      .preview-shell {
        padding: 20px;
      }

      .dialog-actions {
        justify-content: stretch;
      }

      .dialog-actions button {
        flex: 1 1 0;
      }
    }

    @media (forced-colors: active) {
      :root {
        --accent: Highlight;
      }

      body, .preview-shell, dialog, .image-frame, button {
        forced-color-adjust: auto;
      }

      .trigger, .ghost, .destructive {
        border: 1px solid ButtonText;
      }
    }
  </style>
</head>
<body>
  <main>
    <section class="preview-shell" aria-labelledby="page-title">
      <div>
        <h1 id="page-title">Image preview</h1>
        <p class="lede">Review the photo in your library, then choose whether to keep it or delete it.</p>
      </div>

      <figure>
        <div class="image-frame">
          <img
            src="https://images.unsplash.com/photo-1518837695005-2083093ee35b?auto=format&fit=crop&w=1400&q=80"
            alt="Moody mountain landscape with a lake at dusk"
          >
        </div>
        <figcaption>Current library image</figcaption>
      </figure>

      <div class="actions">
        <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
          Delete image
        </button>
      </div>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-desc">
    <div class="dialog-body">
      <div class="dialog-header">
        <div class="dialog-icon" aria-hidden="true">!</div>
        <div>
          <h2 class="dialog-title" id="delete-title">Delete this image?</h2>
          <p class="dialog-copy" id="delete-desc">
            This will remove the image from your library. You can&apos;t undo this action.
          </p>
        </div>
      </div>

      <div class="dialog-actions">
        <button type="button" class="ghost" data-close>Cancel</button>
        <button type="button" class="destructive" data-confirm>Delete image</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById('delete-dialog');
    const openTrigger = document.querySelector('.trigger');
    const closeButton = dialog.querySelector('[data-close]');
    const confirmButton = dialog.querySelector('[data-confirm]');

    openTrigger.addEventListener('click', () => {
      dialog.showModal();
      closeButton.focus();
    });

    closeButton.addEventListener('click', () => {
      dialog.close('cancel');
    });

    confirmButton.addEventListener('click', () => {
      dialog.close('delete');
    });
  </script>
</body>
</html>
