  await page.keyboard.press('Escape');
  await page.waitForTimeout(50);
  assert.strictEqual(await page.locator('#delete-dialog').evaluate(d => d.open), false, 'dialog should close with Escape');
  assert.strictEqual(await page.evaluate(() => document.activeElement?.classList.contains('trigger')), true, 'focus should return to trigger');

  await page.addScriptTag({ content: axe.source });
  const result = await page.evaluate(async () => await window.axe.run());
